arduino.setup:
Serial.begin(9600);
pinMode(${D}, OUTPUT);
pinMode(${CLK}, OUTPUT);
pinMode(${R}, OUTPUT);
pinMode(${Q}, INPUT);
pinMode(${Qbar}, INPUT);
Serial.println("D Flip-Flop (Reset) ready");

arduino.loop:
Serial.println("--- Testing with R=0 ---");
digitalWrite(${R}, LOW);
for (int i=0; i<2; i++) {
  digitalWrite(${D}, i?HIGH:LOW);
  digitalWrite(${CLK}, LOW);
  delay(5);
  digitalWrite(${CLK}, HIGH);
  delay(5);
  Serial.print("D=");
  Serial.print(i);
  Serial.print(" Q=");
  Serial.print(digitalRead(${Q}));
  Serial.print(" Qbar=");
  Serial.println(digitalRead(${Qbar}));
  delay(500);
}
Serial.println("--- Testing R=1 (reset) ---");
digitalWrite(${R}, HIGH);
delay(10);
Serial.print("After R=1: Q=");
Serial.print(digitalRead(${Q}));
Serial.print(" Qbar=");
Serial.println(digitalRead(${Qbar}));
delay(2000);
